127	+package claudecode
128	+
129	+import (
130	+	"context"
131	+	"fmt"
132	+	"os"
133	+	"path/filepath"
134	+
135	+	"github.com/entireio/cli/cmd/entire/cli/agent"
136	+)
137	+
138	+// Ensure ClaudeCodeAgent implements UserHookSupport.
139	+var _ agent.UserHookSupport = (*ClaudeCodeAgent)(nil)
140	+
141	+// UserSettingsPath returns the path of Claude Code's user-level settings file
142	+// (~/.claude/settings.json). It accepts the same hooks schema as the repo's
143	+// .claude/settings.json.
144	+func UserSettingsPath() (string, error) {
145	+	home, err := os.UserHomeDir()
146	+	if err != nil {
147	+		return "", fmt.Errorf("resolve user home directory: %w", err)
148	+	}
149	+	return filepath.Join(home, ".claude", ClaudeSettingsFileName), nil
150	+}
151	+
152	+// InstallUserHooks installs Entire's hooks in ~/.claude/settings.json so they
153	+// fire in every repository (the user-level surface behind global tracking).
154	+// Always the plain production `entire` command form — byte-identical to the
155	+// repo-level production entries, so Claude Code's cross-scope dedup of
156	+// identical hook commands keeps a repo with both installs firing each hook
157	+// once. Never touches user-level permissions and preserves unrelated keys.
158	+func (c *ClaudeCodeAgent) InstallUserHooks(_ context.Context) (int, error) {
159	+	settingsPath, err := UserSettingsPath()
160	+	if err != nil {
161	+		return 0, err
162	+	}
163	+	return installHooksToFile(settingsPath, false, false, false)
164	+}
165	+
166	+// UninstallUserHooks removes Entire's hooks (and only Entire's) from
167	+// ~/.claude/settings.json. A missing file is not an error.
168	+func (c *ClaudeCodeAgent) UninstallUserHooks(_ context.Context) error {
169	+	settingsPath, err := UserSettingsPath()
170	+	if err != nil {
171	+		return err
172	+	}
173	+	return uninstallHooksFromFile(settingsPath, false)
174	+}
175	+
176	+// AreUserHooksInstalled reports whether Entire's hooks are present in
177	+// ~/.claude/settings.json.
178	+func (c *ClaudeCodeAgent) AreUserHooksInstalled(_ context.Context) bool {
179	+	settingsPath, err := UserSettingsPath()
180	+	if err != nil {
181	+		return false
182	+	}
183	+	settings, ok := loadClaudeSettingsFile(settingsPath)
184	+	if !ok {
185	+		return false
186	+	}
187	+	return hasEntireHook(settings.Hooks.Stop)
188	+}
