206	+// No t.Parallel in this file: every test redirects the user home via t.Setenv.
207	+
208	+// setUserHome points os.UserHomeDir at a temp dir (HOME on Unix, USERPROFILE
209	+// on Windows) so user-level installs never touch the developer's real
210	+// ~/.claude/settings.json.
211	+func setUserHome(t *testing.T) string {
212	+	t.Helper()
213	+	home := t.TempDir()
214	+	t.Setenv("HOME", home)
215	+	t.Setenv("USERPROFILE", home)
216	+	return home
217	+}
218	+
219	+func userSettingsTestPath(t *testing.T, home string) string {
220	+	t.Helper()
221	+	return filepath.Join(home, ".claude", ClaudeSettingsFileName)
222	+}
