224	+func writeUserClaudeSettings(t *testing.T, home, content string) {
225	+	t.Helper()
226	+	path := userSettingsTestPath(t, home)
227	+	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
228	+		t.Fatal(err)
229	+	}
230	+	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
231	+		t.Fatal(err)
232	+	}
233	+}
234	+
235	+func readRawSettings(t *testing.T, path string) map[string]json.RawMessage {
236	+	t.Helper()
237	+	data, err := os.ReadFile(path)
238	+	if err != nil {
239	+		t.Fatalf("read settings: %v", err)
240	+	}
241	+	var raw map[string]json.RawMessage
242	+	if err := json.Unmarshal(data, &raw); err != nil {
243	+		t.Fatalf("parse settings: %v", err)
244	+	}
245	+	return raw
246	+}
247	+
248	+// collectHookCommands returns every hook command in the settings file at path.
249	+func collectHookCommands(t *testing.T, path string) []string {
250	+	t.Helper()
251	+	raw := readRawSettings(t, path)
252	+	hooksRaw, ok := raw["hooks"]
253	+	if !ok {
254	+		return nil
255	+	}
256	+	var hooks map[string][]ClaudeHookMatcher
257	+	if err := json.Unmarshal(hooksRaw, &hooks); err != nil {
258	+		t.Fatalf("parse hooks: %v", err)
259	+	}
260	+	var cmds []string
261	+	for _, matchers := range hooks {
262	+		for _, m := range matchers {
263	+			for _, h := range m.Hooks {
264	+				cmds = append(cmds, h.Command)
265	+			}
266	+		}
267	+	}
268	+	return cmds
269	+}
270	+
271	+const existingUserSettings = `{
272	+  "model": "opus",
273	+  "env": {"FOO": "bar"},
274	+  "permissions": {"deny": ["Read(secret.txt)"]},
275	+  "hooks": {
276	+    "Notification": [{"matcher": "", "hooks": [{"type": "command", "command": "custom-notify"}]}],
277	+    "Stop": [{"matcher": "", "hooks": [{"type": "command", "command": "my-own-stop"}]}]
278	+  }
279	+}`
280	+
281	+func TestInstallUserHooks_MergesWithoutClobberingUnrelatedKeys(t *testing.T) {
282	+	home := setUserHome(t)
283	+	writeUserClaudeSettings(t, home, existingUserSettings)
284	+
285	+	agent := &ClaudeCodeAgent{}
286	+	count, err := agent.InstallUserHooks(context.Background())
287	+	if err != nil {
288	+		t.Fatalf("InstallUserHooks() error = %v", err)
289	+	}
290	+	if count == 0 {
291	+		t.Fatal("InstallUserHooks() installed nothing on a file without Entire hooks")
292	+	}
293	+
294	+	raw := readRawSettings(t, userSettingsTestPath(t, home))
295	+	if got := string(raw["model"]); got != `"opus"` {
296	+		t.Errorf("model clobbered: %s", got)
297	+	}
298	+	if got := string(raw["env"]); !strings.Contains(got, `"FOO"`) {
299	+		t.Errorf("env clobbered: %s", got)
300	+	}
301	+	// User-level installs must never touch user permissions (the deny rule is
302	+	// repo-scope only).
303	+	if got := string(raw["permissions"]); got != `{"deny":["Read(secret.txt)"]}` && !strings.Contains(got, "secret.txt") {
304	+		t.Errorf("permissions clobbered: %s", got)
305	+	}
306	+	if strings.Contains(string(raw["permissions"]), ".entire/metadata") {
307	+		t.Errorf("repo-scoped deny rule leaked into user permissions: %s", raw["permissions"])
308	+	}
309	+
310	+	cmds := collectHookCommands(t, userSettingsTestPath(t, home))
311	+	var foundCustomStop, foundNotify, foundEntireStop bool
312	+	for _, c := range cmds {
313	+		switch {
314	+		case c == "my-own-stop":
315	+			foundCustomStop = true
316	+		case c == "custom-notify":
317	+			foundNotify = true
318	+		case isEntireHook(c) && strings.Contains(c, "entire hooks claude-code stop"):
319	+			foundEntireStop = true
320	+		}
321	+		// The plain production form only — never a repo-local dev path.
322	+		if strings.Contains(c, "CLAUDE_PROJECT_DIR") || strings.Contains(c, "entire-dev") {
323	+			t.Errorf("user-level hook uses a repo-local command form: %s", c)
324	+		}
325	+	}
326	+	if !foundCustomStop || !foundNotify {
327	+		t.Errorf("user's own hooks were removed (customStop=%v notify=%v)", foundCustomStop, foundNotify)
328	+	}
329	+	if !foundEntireStop {
330	+		t.Errorf("Entire stop hook missing from user settings, commands: %v", cmds)
331	+	}
332	+	if !agent.AreUserHooksInstalled(context.Background()) {
333	+		t.Error("AreUserHooksInstalled() = false after install")
334	+	}
335	+}
