337	+func TestInstallUserHooks_Idempotent(t *testing.T) {
338	+	home := setUserHome(t)
339	+
340	+	agent := &ClaudeCodeAgent{}
341	+	first, err := agent.InstallUserHooks(context.Background())
342	+	if err != nil {
