+func writeUserClaudeSettings(t *testing.T, home, content string) {
+	t.Helper()
+	path := userSettingsTestPath(t, home)
+	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
+		t.Fatal(err)
+	}
+}
