32			return unreadableUserSettingsError(err)
33		}
34		if us.Global == nil {
35			us.Global = &settings.GlobalConfig{}
36		}
37		us.Global.Enabled = true
38		if err := settings.SaveUserSettings(ctx, us); err != nil {
39			return fmt.Errorf("saving user settings: %w", err)
40		}
41		fmt.Fprintln(w, "Global tracking enabled.")
42		fmt.Fprintln(w, "Entire now tracks agent sessions in every repo on this machine that has no repo-level setup.")
43		installUserAgentHooks(ctx, w)
44		return nil
45	}
46	
47	// installUserAgentHooks installs user-level agent hooks for every registered
48	// agent that supports them and reports the outcome per agent. User-level
49	// hooks are what let a session in a never-enabled repo fire a hook at all, so
50	// they are the activation step of enable --global. Per-agent failures are
51	// reported and skipped: global tracking is already on at this point, and one
52	// broken user config file must not block the other agents. Writes only
53	// user-scope config — never a repo file.
54	func installUserAgentHooks(ctx context.Context, w io.Writer) {
55		fmt.Fprintln(w, "User-level agent hooks:")
56		var unsupported []string
57		for _, name := range agent.List() {
58			ag, err := agent.Get(name)
59			if err != nil {
60				continue
61			}
62			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
63				continue
64			}
65			uhs, ok := agent.AsUserHookSupport(ag)
66			if !ok {
67				unsupported = append(unsupported, string(name))
68				continue
69			}
70			count, err := uhs.InstallUserHooks(ctx)
71			switch {
72			case err != nil:
73				fmt.Fprintf(w, "  ! %s: install failed: %v\n", name, err)
74			case count == 0:
75				fmt.Fprintf(w, "  ✓ %s: already installed\n", name)
76			default:
77				fmt.Fprintf(w, "  ✓ %s: installed\n", name)
78			}
79		}
80		if len(unsupported) > 0 {
81			fmt.Fprintf(w, "  - user-level hooks not supported: %s\n", strings.Join(unsupported, ", "))
82		}
83	}
84	
85	// installedUserHookAgents returns the registered, non-test agents whose
86	// user-level hooks are currently installed.
87	func installedUserHookAgents(ctx context.Context) []agent.UserHookSupport {
88		var installed []agent.UserHookSupport
89		for _, name := range agent.List() {
90			ag, err := agent.Get(name)
91			if err != nil {
92				continue
93			}
94			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
95				continue
96			}
97			if uhs, ok := agent.AsUserHookSupport(ag); ok && uhs.AreUserHooksInstalled(ctx) {
98				installed = append(installed, uhs)
99			}
100		}
101		return installed
102	}
103	
104	// maybeRemoveUserAgentHooks offers to remove Entire's user-level agent hooks
105	// after disable --global. Removal only ever touches entries recognized as
106	// Entire's. Interactive runs confirm first; non-interactive runs remove ours
107	// without asking. A declined or aborted prompt leaves the hooks in place —
108	// they gate on the (now off) global tier, so they are inert until removed.
109	func maybeRemoveUserAgentHooks(ctx context.Context, w io.Writer) {
110		installed := installedUserHookAgents(ctx)
111		if len(installed) == 0 {
112			return
113		}
114		remove := true
115		if interactive.CanPromptInteractively() {
116			form := NewAccessibleForm(
117				huh.NewGroup(
118					huh.NewConfirm().
119						Title("Also remove Entire's user-level agent hooks?").
120						Description("Removes only Entire's entries from the agents' user-level settings.").
121						Affirmative("Yes").
122						Negative("No").
123						Value(&remove),
124				),
125			)
126			if err := form.Run(); err != nil {
127				if !errors.Is(err, huh.ErrUserAborted) && !errors.Is(err, context.Canceled) {
128					logging.Debug(ctx, "user hook removal prompt failed", "error", err)
129				}
130				remove = false
131			}
132		}
133		if !remove {
134			fmt.Fprintln(w, "User-level agent hooks left in place (inert while global tracking is off); run 'entire disable --global' again to remove them.")
135			return
136		}
137		for _, uhs := range installed {
138			if err := uhs.UninstallUserHooks(ctx); err != nil {
139				fmt.Fprintf(w, "  ! %s: could not remove user-level hooks: %v\n", uhs.Name(), err)
140				continue
141			}
142			fmt.Fprintf(w, "  ✓ %s: user-level hooks removed\n", uhs.Name())
143		}
144	}
145	
146	// runDisableGlobalMode turns the user-global tracking tier off. The answer is
147	// durable: the file keeps global.enabled=false (rather than being removed), so
148	// the setup wizard never re-asks. Repo-level settings are not touched.
149	func runDisableGlobalMode(ctx context.Context, w io.Writer) error {
150		us, err := settings.LoadUserSettings(ctx)
151		if err != nil {
152			return unreadableUserSettingsError(err)
153		}
154		if us.Global == nil {
155			us.Global = &settings.GlobalConfig{}
156		}
157		us.Global.Enabled = false
158		if err := settings.SaveUserSettings(ctx, us); err != nil {
159			return fmt.Errorf("saving user settings: %w", err)
160		}
161		fmt.Fprintln(w, "Global tracking disabled.")
162		maybeRemoveUserAgentHooks(ctx, w)
163		return nil
164	}
165	
166	// unreadableUserSettingsError turns a LoadUserSettings failure into an
167	// actionable message: the strict decoder also rejects files written by a
168	// newer CLI, so name the file and both ways out.
169	func unreadableUserSettingsError(err error) error {
170		return fmt.Errorf("cannot update user settings at %s: %w; upgrade entire or remove the unknown key",
171			settings.UserSettingsPath(), err)
172	}
173	
174	// maybeAskGlobalTracking asks the one-time machine-wide tracking question
175	// during interactive setup. It never asks when the global tier is already
176	// configured (either answer), and never prompts in non-interactive contexts
177	// (--yes, no TTY) — those get the one-line hint instead. An answered prompt
178	// is persisted either way, so the question is never asked twice; a cancelled
179	// prompt saves nothing, so a later enable can ask again.
180	func maybeAskGlobalTracking(ctx context.Context, w io.Writer, opts EnableOptions) {
181		us, err := settings.LoadUserSettings(ctx)
182		if err != nil || us.Global != nil {
183			// A malformed user settings file must never be overwritten from a
184			// side prompt; a configured one must never re-ask.
185			return
186		}
187		if opts.Yes || !interactive.CanPromptInteractively() {
188			fmt.Fprintln(w, globalTrackingHint)
189			return
190		}
191		enable := false
192		form := NewAccessibleForm(
193			huh.NewGroup(
194				huh.NewConfirm().
195					Title("Also track every repo on this machine automatically?").
196					Description("Applies to repos without their own Entire setup.").
197					Affirmative("Yes").
198					Negative("No").
199					Value(&enable),
200			),
201		)
202		if err := form.Run(); err != nil {
203			// Ctrl-C stays silent (nothing saved, a later enable asks again);
204			// any other prompt failure must at least be diagnosable.
205			if !errors.Is(err, huh.ErrUserAborted) && !errors.Is(err, context.Canceled) {
206				logging.Debug(ctx, "global tracking prompt failed", "error", err)
207			}
208			return
209		}
210		us.Global = &settings.GlobalConfig{Enabled: enable}
211		if err := settings.SaveUserSettings(ctx, us); err != nil {
212			fmt.Fprintf(w, "Warning: could not save the global tracking answer: %v\n", err)
213			return
214		}
215		if enable {
216			fmt.Fprintln(w, "  ✓ Global tracking enabled")
217			// The wizard's yes is the same commitment as enable --global, so it
218			// triggers the same user-level hook install (user-scope config only).
219			installUserAgentHooks(ctx, w)
220		}
221	}
222	
223	// printGlobalTrackingHintIfUnconfigured prints the enable --global pointer on
224	// enable paths that must never prompt (--agent), when the machine-wide
225	// question has never been answered.
226	func printGlobalTrackingHintIfUnconfigured(ctx context.Context, w io.Writer) {
227		us, err := settings.LoadUserSettings(ctx)
228		if err != nil || us.Global != nil {
229			return
230		}
231		fmt.Fprintln(w, globalTrackingHint)
232	}
233	
234	// globalRuntimeSubdirs are the runtime subtrees invisible routing places
235	// under the worktree's namespace dir (<git-common-dir>/entire/worktree/
236	// <worktree-key>) for globally tracked repos, relative to that base and to
237	// the worktree's .entire directory alike.
238	var globalRuntimeSubdirs = []string{"metadata", "logs", "tmp"}
239	
240	// maybeMigrateGlobalRuntimeData moves THIS worktree's invisible-routed
241	// runtime data (<git-common-dir>/entire/worktree/<worktree-key>/
242	// {metadata,logs,tmp}) into the worktree's .entire directory. Repo-level
243	// enable flows call it BEFORE writing .entire/settings.json: that write
244	// flips path routing to the worktree, which would otherwise strand the
245	// routed files in .git. Only the current worktree's namespace is touched —
246	// sibling worktrees of the same clone keep their own namespaces (and their
247	// in-flight sessions) untouched. It triggers when the clone preferences
248	// carry the globally_enabled marker or when the routed directory is
249	// non-empty. Best-effort by contract — enable never aborts on migration
250	// failure; files that could not be moved stay in place for a later retry and
251	// the outcome is summarized in one line.
252	func maybeMigrateGlobalRuntimeData(ctx context.Context, w io.Writer) {
253		root, err := paths.WorktreeRoot(ctx)
254		if err != nil {
255			return
256		}
257		commonDir, err := session.GetGitCommonDir(ctx)
258		if err != nil {
259			return
260		}
261		// session.GetGitCommonDir can return a cwd-relative path (e.g. ".git").
262		commonDir, err = filepath.Abs(commonDir)
263		if err != nil {
264			return
265		}
266		source, err := paths.InvisibleRuntimeDir(commonDir, root)
267		if err != nil {
268			return
269		}
270	
271		triggered := false
272		if prefs, prefsErr := settings.LoadClonePreferences(ctx); prefsErr == nil && prefs.GloballyEnabled {
273			triggered = true
274		}
275		if !triggered {
276			entries, readErr := os.ReadDir(source)
277			if readErr != nil || len(entries) == 0 {
278				return
279			}
280		}
281	
282		var moved, skipped, failed int
283		for _, sub := range globalRuntimeSubdirs {
284			m, s, f := moveDirContents(filepath.Join(source, sub), filepath.Join(root, paths.EntireDir, sub))
285			moved += m
286			skipped += s
287			failed += f
288		}
289		removeEmptyDirTree(source)
290		// The parent (<git-common-dir>/entire/worktree) is shared with sibling
291		// worktrees' namespaces; os.Remove only succeeds once the last namespace
292		// is gone, which is exactly the desired cleanup.
293		_ = os.Remove(filepath.Dir(source))
294	
295		if moved+skipped+failed == 0 {
296			return
297		}
298		// ✓ elsewhere in the enable output means unqualified success, so drop it
299		// when anything failed, and name the source so leftovers are findable.
300		prefix := "  ✓ "
301		if failed > 0 {
302			prefix = "  "
303		}
304		line := fmt.Sprintf("%sMoved %d globally-tracked session file(s) into .entire/", prefix, moved)
305		if skipped > 0 {
306			line += fmt.Sprintf(", %d already present", skipped)
307		}
308		if failed > 0 {
309			line += fmt.Sprintf(", %d could not be moved (left in %s)", failed, source)
310		}
311		fmt.Fprintln(w, line)
312	}
313	
314	// migrateRenameFile is the rename used by moveDirContents; a seam so tests
315	// can force the cross-device (EXDEV) fallback deterministically.
316	var migrateRenameFile = os.Rename
317	
318	// moveDirContents moves every file under src into the same relative location
319	// under dst, creating directories as needed. Files already present in dst are
320	// skipped (left in src). Returns moved/skipped/failed counts; a missing src is
321	// (0, 0, 0).
322	func moveDirContents(src, dst string) (moved, skipped, failed int) {
323		entries, err := os.ReadDir(src)
324		if err != nil {
325			return 0, 0, 0
326		}
327		for _, entry := range entries {
328			srcPath := filepath.Join(src, entry.Name())
329			dstPath := filepath.Join(dst, entry.Name())
330			if entry.IsDir() {
331				m, s, f := moveDirContents(srcPath, dstPath)
332				moved, skipped, failed = moved+m, skipped+s, failed+f
333				continue
334			}
335			if _, statErr := os.Lstat(dstPath); statErr == nil {
336				skipped++
337				continue
338			}
339			//nolint:gosec // G301: runtime-data dirs match the .entire directory permissions
340			if mkErr := os.MkdirAll(dst, 0o755); mkErr != nil {
341				failed++
342				continue
343			}
344			if renameErr := migrateRenameFile(srcPath, dstPath); renameErr != nil {
345				// Rename fails with EXDEV when the git common dir and the
346				// worktree live on different filesystems (--separate-git-dir,
347				// linked worktree on another volume); fall back to copy+remove.
348				if copyErr := copyFileThenRemove(srcPath, dstPath); copyErr != nil {
349					failed++
350					continue
351				}
352			}
353			moved++
354		}
355		return moved, skipped, failed
356	}
357	
358	// copyFileThenRemove copies src to dst (temp file in dst's directory, then
359	// rename, so a partial copy is never left at dst) and removes src on success.
360	// Only regular files are copied; anything else stays behind as failed.
361	func copyFileThenRemove(src, dst string) error {
362		info, err := os.Lstat(src)
363		if err != nil {
364			return fmt.Errorf("stat source: %w", err)
365		}
366		if !info.Mode().IsRegular() {
367			return fmt.Errorf("not a regular file: %s", src)
368		}
369		in, err := os.Open(src) //nolint:gosec // path is derived from the git common dir, not user input
370		if err != nil {
371			return fmt.Errorf("open source: %w", err)
372		}
373		defer in.Close()
374		tmp, err := os.CreateTemp(filepath.Dir(dst), filepath.Base(dst)+".tmp-*")
375		if err != nil {
376			return fmt.Errorf("create temp: %w", err)
377		}
378		tmpName := tmp.Name()
379		removeTmp := true
380		defer func() {
381			if removeTmp {
382				_ = os.Remove(tmpName)
383			}
384		}()
385		if _, err := io.Copy(tmp, in); err != nil {
386			_ = tmp.Close()
387			return fmt.Errorf("copy contents: %w", err)
388		}
389		if err := tmp.Chmod(info.Mode().Perm()); err != nil {
390			_ = tmp.Close()
391			return fmt.Errorf("chmod temp: %w", err)
392		}
393		if err := tmp.Close(); err != nil {
394			return fmt.Errorf("close temp: %w", err)
395		}
396		if err := os.Rename(tmpName, dst); err != nil {
397			return fmt.Errorf("rename into place: %w", err)
398		}
399		removeTmp = false
400		if err := os.Remove(src); err != nil {
401			return fmt.Errorf("remove source: %w", err)
402		}
403		return nil
404	}
405	
406	// removeEmptyDirTree removes the now-empty directories left behind by
407	// moveDirContents, deepest first, including root itself. Non-empty
408	// directories (skipped or failed files) are left in place.
409	func removeEmptyDirTree(root string) {
410		entries, err := os.ReadDir(root)
411		if err != nil {
412			return
413		}
414		for _, entry := range entries {
415			if entry.IsDir() {
416				removeEmptyDirTree(filepath.Join(root, entry.Name()))
417			}
418		}
419		// os.Remove fails on non-empty directories, which is exactly the
420		// keep-what-couldn't-move behavior wanted here.
421		if err := os.Remove(root); err != nil {
422			return
423		}
424	}
